import{_ as e,o as d,c as i,ae as a}from"./chunks/framework.EHGTsUvI.js";const b=JSON.parse('{"title":"Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/permissions.md","filePath":"extensions/permissions.md"}'),s={name:"extensions/permissions.md"};function r(o,t,n,c,h,l){return d(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h1><p>Extensions must declare required permissions in <code>extension.json</code>. High-risk permissions require explicit user approval.</p><h2 id="available-permissions" tabindex="-1">Available Permissions <a class="header-anchor" href="#available-permissions" aria-label="Permalink to &quot;Available Permissions&quot;">​</a></h2><h3 id="filesystem" tabindex="-1">Filesystem <a class="header-anchor" href="#filesystem" aria-label="Permalink to &quot;Filesystem&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>fs:read</code></td><td>Read files within share paths</td></tr><tr><td><code>fs:write</code></td><td>Write files within share paths</td></tr><tr><td><code>fs:delete</code></td><td>Delete files within share paths</td></tr></tbody></table><h3 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>net:http</code></td><td>Make HTTP requests (100 req/min, 30s timeout)</td></tr><tr><td><code>net:ws</code></td><td>WebSocket connections</td></tr><tr><td><code>net:listen</code></td><td>Listen on a port</td></tr></tbody></table><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>config:read</code></td><td>Read extension config</td></tr><tr><td><code>config:write</code></td><td>Write extension config</td></tr></tbody></table><h3 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>identity:read</code></td><td>Read handle and public key</td></tr><tr><td><code>identity:write</code></td><td>Modify identity settings</td></tr></tbody></table><h3 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>shares:read</code></td><td>List and read share metadata</td></tr><tr><td><code>shares:write</code></td><td>Create or modify shares</td></tr><tr><td><code>transfers:read</code></td><td>Read transfer history and stats</td></tr><tr><td><code>peers:read</code></td><td>List pals</td></tr><tr><td><code>messages:send</code></td><td>Send chat messages</td></tr><tr><td><code>messages:read</code></td><td>Read chat messages</td></tr></tbody></table><h3 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>schedule:write</code></td><td>Create scheduled tasks</td></tr><tr><td><code>clipboard</code></td><td>Access clipboard</td></tr><tr><td><code>notifications</code></td><td>Show OS notifications</td></tr><tr><td><code>audit:read</code></td><td>Read audit log</td></tr><tr><td><code>audit:write</code></td><td>Write to audit log</td></tr></tbody></table><h3 id="special" tabindex="-1">Special <a class="header-anchor" href="#special" aria-label="Permalink to &quot;Special&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>exec:&lt;command&gt;</code></td><td>Execute a specific system command (e.g., <code>exec:clamdscan</code>)</td></tr></tbody></table><h2 id="high-risk-permissions" tabindex="-1">High-Risk Permissions <a class="header-anchor" href="#high-risk-permissions" aria-label="Permalink to &quot;High-Risk Permissions&quot;">​</a></h2><p>These require explicit user approval before the extension can run:</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>fs:write</code>, <code>fs:delete</code>, <code>net:http</code>, <code>net:ws</code>, <code>messages:send</code>, <code>shares:write</code></p></div><p>Extensions requesting 3+ high-risk permissions are classified as high-risk.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Maximum <strong>10 permissions</strong> per extension</li><li>Maximum <strong>20 hooks</strong> per extension</li><li>Permissions checked on every API call at runtime</li></ul>',23)])])}const p=e(s,[["render",r]]);export{b as __pageData,p as default};
